1	// THE CORE GENERIC EXTRACTOR — the one extractor that runs on every page,
2	// whatever its host. It scrapes a best-effort event from any page's own
3	// self-description, and it is the BASE LAYER of the whole pipeline:
4	//   - on a host with no per-site source, it is the only extractor, and the popup
5	//     shows its event as a calendar button when it's complete enough (title +
6	//     location + start) and the host isn't denylisted, otherwise/also using it to
7	//     pre-fill the "request this source" form (events-popup/popup.js's chooseContent);
8	//   - on a supported host, assemble-events.js runs it FIRST and merges the site's
9	//     source over it, so a per-site extractor only has to state the fields this
10	//     one gets wrong (event-extractors/custom/<site>.js);
11	//   - on a supported host with no per-site source, it IS the site's support —
12	//     such a site is fully supported (supportedDomains lists it) with no
13	//     extractor file of its own.
14	//
15	// It sits beside the registry and the orchestrator rather than under custom/:
16	// that folder is the extensibility point, one file per site, and this is a
17	// different thing — the one fixed, site-agnostic reader every one of those files
18	// layers over. Nothing here may know about a specific site.
19	//
20	// extract() returns an array of the page's best-effort events (empty when the
21	// page describes none), which assemble-events.js normalizes and presents. It
22	// combines two best-effort signals, first non-empty value per field winning:
23	//   1. events the page embeds about itself (GCal.embeddedEvents — schema.org)
24	//   2. generic heuristics over the page's meta tags, microdata, <time>, and text
25	//
26	// Generic heuristics, each tried against progressively weaker signals:
27	//   title       og:title meta tag -> the page's <h1> -> document title
28	//   start/end   microdata (itemprop="startDate"/"endDate", on <meta> or
29	//               <time> elements) -> event:start_time/end_time meta tags ->
30	//               the first <time datetime="..."> on the page -> the first
31	//               date-and-time pattern in the page's visible text
32	//               ("June 14, 2026 at 7 PM", "14 June 2026", "6/14/2026", ISO)
33	//   location    itemprop="location" -> <address> -> the first reasonably
34	//               short element whose class/id mentions "venue" or "location" ->
35	//               OG place/business/geo meta tags -> the "@ Venue" title tail ->
36	//               an "(Online)"-style title parenthetical -> the street address
37	//               in the page's footer/header chrome (single-venue sites)
38	//   description og:description or description meta tag ->
39	//               itemprop="description" (line breaks preserved)
40	//   all-day     a start–end pair covering whole calendar days (00:00 -> 23:59)
41	//               is the all-day convention, collapsed to the date-only form
42	//               (helpers/dates.js's allDayRange)
43	//   ctz         derived only when two independent page-declared hints agree (a
44	//               stated inline-JSON timezone, the events' own UTC offsets, the
45	//               JSON-LD venue country, the page locale) — see
46	//               helpers/derive-timezone.js (#674); otherwise absent
47	(() => {
48	  const { clean, text, meta, blockText, htmlToText, bodyText, normalizeDateValue, parseDateFromText, endFromTimeRange, allDayRange, merge, embeddedEvents, parts, deriveCtz } = GCal;
49	
50	  // How much of the page's body text the date/time scan below considers. Large
51	  // enough to reach past a long nav/menu block (e.g. a WordPress mega-menu)
52	  // that sits before the real content on some sites, small enough to stay a
53	  // deliberate "near the top of the page" heuristic rather than a full-page scan.
54	  const BODY_TEXT_SCAN_LIMIT = 16000;
55	
56	  function extract() {
57	    const embedded = embeddedEvents.find();
58	    // Ambiguous numeric dates ("05/07/2026") are read day-first when the page
59	    // declares a non-US locale — the DD/MM/YYYY convention most of the world
60	    // (and every non-US site here) writes, in both JSON-LD and visible text.
61	    const dayFirst = pageUsesDayFirstDates();
62	    // Several embedded events => a listing page; surface each.
63	    if (embedded.length > 1) return collapseAllDay(withCtz(embedded.map((ld) => embeddedEvents.toEvent(ld, dayFirst)).map(trimVenueTitle)));
64	
65	    const event = trimVenueTitle(merge(embeddedEvents.toEvent(embedded[0], dayFirst), heuristics(dayFirst)));
66	    // The heuristics always fill a title (og:title -> <h1> -> document title),
67	    // present on essentially every page, so a title alone is not an event. Treat
68	    // this as an event only when the page embedded one or a date was parsed.
69	    return embedded.length > 0 || event.start ? collapseAllDay(withCtz([event])) : [];
70	  }
71	
72	  // Rewrite any event whose start–end pair spans whole calendar days
73	  // (00:00 → 23:59, helpers/dates.js's allDayRange) into the date-only all-day
74	  // form the string contract uses. Runs last, over the finished events, so it
75	  // sees the merged start/end whichever signal supplied them — and after
76	  // withCtz, since a floating midnight carries no offset hint for deriveCtz to
77	  // read either way.
78	  function collapseAllDay(events) {
79	    for (const e of events) {
80	      const range = allDayRange(e.start, e.end);
81	      if (range) {
82	        e.start = range.start;
83	        e.end = range.end;
84	      }
85	    }
86	    return events;
87	  }
88	
89	  // Whether the page's own declared locale is a day-first one (DD/MM/YYYY) — the
90	  // everyday format outside the US, so an ambiguous numeric slash date should be
91	  // read day-first (see helpers/dates.js). Conservative: only a POSITIVE non-US
92	  // locale signal flips it — an explicit region that isn't US (he-IL, en-GB, …)
93	  // or a non-English language; a bare "en" (region unknown) keeps the safe
94	  // month-first default rather than guessing. Mirrors derive-timezone.js's read
95	  // of <html lang> / og:locale.
96	  function pageUsesDayFirstDates() {
97	    const MONTH_FIRST_REGIONS = new Set(["US"]);
98	    const langAttr = document.documentElement ? document.documentElement.getAttribute("lang") : "";
99	    for (const raw of [langAttr, meta("og:locale")]) {
100	      const m = /^([a-z]{2,3})(?:[-_]([a-z]{2}))?/i.exec(clean(raw));
101	      if (!m) continue;
102	      const region = (m[2] || "").toUpperCase();
103	      if (region) return !MONTH_FIRST_REGIONS.has(region);
104	      if (m[1].toLowerCase() !== "en") return true;
105	    }
106	    return false;
107	  }
108	
109	  // The one field the heuristics can never scrape directly: the event's
110	  // timezone. deriveCtz (helpers/derive-timezone.js) answers only when two
111	  // independent page-declared hints agree; a "" answer leaves the events
112	  // exactly as before (#674). Page-level on purpose: every event on the page
113	  // shares the one corroborated zone, and a page whose events span zones never
114	  // gets one (the offset/country unanimity rules see to it).
115	  function withCtz(events) {
116	    const ctz = deriveCtz(events.flatMap((e) => [e.start, e.end]));
117	    if (ctz) for (const e of events) e.ctz = ctz;
118	    return events;
119	  }
120	
121	  // "Event @ Venue" titles (bandsintown, Songkick, and many music/ticketing
122	  // listings — whether the title arrives via JSON-LD or og:title) repeat the venue
123	  // in the title. When a FULLER location is known — one that leads with that same
124	  // venue but carries more (street, city, country) — the "@ Venue" tail is
125	  // redundant, so trim the title to the event name alone, the way a dedicated
126	  // source reads it. Guarded to a strict superset (the location starts with the
127	  // venue but is longer) so we only strip when the venue is known independently: a
128	  // location that is exactly the title's tail (e.g. one parsed back out of the
129	  // title by venueFromTitle) leaves the title untouched.
130	  function trimVenueTitle(event) {
131	    if (!event || !event.title) return event;
132	    const at = event.title.indexOf(" @ ");
133	    if (at < 0) return event;
134	    const venueTail = clean(event.title.slice(at + 3));
135	    const loc = clean(event.location);
136	    if (venueTail && loc && loc !== venueTail && loc.startsWith(venueTail)) {
137	      event.title = clean(event.title.slice(0, at));
138	    }
139	    return event;
140	  }
141	
142	  // Best-effort scrape of any page's meta tags / microdata / text. `dayFirst`
143	  // (see extract) is forwarded to every date parse so an ambiguous numeric slash
144	  // date is read day-first on a non-US-locale page.
145	  function heuristics(dayFirst) {
146	    const out = {};
147	
148	    out.title = stripSiteSuffix(meta("og:title")) || text("h1") || clean(document.title);
149	
150	    const startProp = document.querySelector('[itemprop="startDate"]');
151	    if (startProp) {
152	      out.start = normalizeDateValue(
153	        startProp.getAttribute("content") || startProp.getAttribute("datetime") || startProp.textContent,
154	        dayFirst
155	      );
156	    }
157	    const endProp = document.querySelector('[itemprop="endDate"]');
158	    if (endProp) {
159	      out.end = normalizeDateValue(
160	        endProp.getAttribute("content") || endProp.getAttribute("datetime") || endProp.textContent,
161	        dayFirst
162	      );
163	    }
164	    if (!out.start) {
165	      out.start = meta("event:start_time");
166	      out.end = out.end || meta("event:end_time");
167	    }
168	    if (!out.start) {
169	      const timeEl = document.querySelector("time[datetime]");
170	      if (timeEl) out.start = normalizeDateValue(timeEl.getAttribute("datetime"), dayFirst);
171	    }
172	    if (!out.start) {
173	      const body = bodyText().slice(0, BODY_TEXT_SCAN_LIMIT);
174	      out.start = parseDateFromText(body, dayFirst);
175	      // A start scraped from text often sits next to its end as a time range
176	      // ("6:30 pm - 10:00 pm"); recover the end when nothing structured gave one.
177	      if (out.start && !out.end) out.end = endFromTimeRange(body, out.start);
178	    } else if (!out.start.includes("T") || /T00:00(?::00)?/.test(out.start)) {
179	      // <time datetime> (or microdata) gave date-only or midnight-UTC — a common
180	      // placeholder pattern. Try metadata descriptions first (curated, one focused
181	      // sentence vs the whole page), then body text, for a timed start on the same
182	      // date; if found, prefer it over the midnight placeholder.
183	      const datePrefix = out.start.slice(0, 10);
184	      const body = bodyText().slice(0, BODY_TEXT_SCAN_LIMIT);
185	      for (const src of [meta("og:description"), meta("description"), body]) {
186	        const refined = parseDateFromText(src, dayFirst);
187	        if (refined && refined.includes("T") && refined.startsWith(datePrefix)) {
188	          out.start = refined;
189	          if (!out.end) out.end = endFromTimeRange(src, out.start);
190	          break;
191	        }
192	      }
193	    }
194	
195	    out.location =
196	      text('[itemprop="location"]') ||
197	      text("address") ||
198	      shortText('[class*="venue" i], [class*="location" i], [id*="location" i]') ||
199	      metaLocation() ||
200	      venueFromTitle(out.title);
201	    // A "(Virtual)", "(Online)", or "(Webinar)" parenthetical in the event title
202	    // signals a virtual event with no physical venue — a convention used by many
203	    // event platforms (EventBrite, Meetup, Luma, …).
204	    if (!out.location && /\((virtual|online|webinar)\)/i.test(out.title || "")) {
205	      out.location = "Online";
206	    }
207	    // Dead last — even the "(Online)" inference above outranks it, because site
208	    // chrome describes the site, not this event.
209	    if (!out.location) out.location = chromeAddress();
210	
211	    // Preserve the description's line breaks. Meta descriptions often contain
212	    // literal HTML markup (e.g. "<br />") rather than real newlines — parse
213	    // them through htmlToText so markup becomes text structure.
214	    const rawDesc = meta("og:description") || meta("description");
215	    out.description = rawDesc ? htmlToText(rawDesc) : blockText('[itemprop="description"]');
216	
217	    return out;
218	  }
219	
220	  // og:title often ends with the site's own name (" - Tel Aviv Cinematheque",
221	  // "… - Think&Drink"); drop that trailing " <sep> <site name>" so the generic
222	  // title is just the event, the way a per-site source would read it. Only the
223	  // exact og:site_name is stripped, so a real title that merely contains a dash
224	  // is left alone.
225	  function stripSiteSuffix(title) {
226	    title = clean(title);
227	    const site = clean(meta("og:site_name"));
228	    if (!title || !site) return title;
229	    for (const sep of [" - ", " | ", " – ", " — "]) {
230	      const suffix = sep + site;
231	      if (title.endsWith(suffix)) return clean(title.slice(0, -suffix.length));
232	    }
233	    return title;
234	  }
235	
236	  // Last-resort location: the place meta tags some pages publish (the Open Graph
237	  // "place"/"business" address fields, or the geo.* tags) when nothing on the
238	  // page exposed a location via microdata, <address>, or a venue/location class.
239	  // Composed into one comma-separated string, most specific part first; the
240	  // coordinate (lat/long) tags are deliberately ignored — they're not a venue.
241	  function metaLocation() {
242	    const p = parts();
243	    p.add(meta("og:title:place") || meta("place:name") || meta("geo.placename"));
244	    p.add(meta("og:street-address") || meta("business:contact_data:street_address"));
245	    p.add(meta("og:locality") || meta("business:contact_data:locality"));
246	    p.add(meta("og:region") || meta("business:contact_data:region") || meta("geo.region"));
247	    p.add(meta("og:postal-code") || meta("business:contact_data:postal_code"));
248	    p.add(meta("og:country-name") || meta("business:contact_data:country_name"));
249	    return p.join();
250	  }
251	
252	  // Last-resort location: many event/listing pages title themselves
253	  // "Event @ Venue" (bandsintown, secrettelaviv, Songkick, …). When nothing more
254	  // structured exposed a location, take the part after the first " @ " in the
255	  // page title as a best-effort venue. Bounded in length so a stray "@" in a
256	  // long title doesn't turn a whole sentence into a location.
257	  function venueFromTitle(title) {
258	    const i = (title || "").indexOf(" @ ");
259	    if (i < 0) return "";
260	    const venue = clean(title.slice(i + 3));
261	    return venue.length <= 80 ? venue : "";
262	  }
263	
264	  // Href of a maps service — a "directions to us" link marks its own text as
265	  // the site's street address.
266	  const MAPS_SERVICE = /(?:maps\.google\.|google\.[a-z.]+\/maps|waze\.com|openstreetmap\.org|maps\.apple\.com|bing\.com\/maps)/i;
267	  // An icon file whose name says "this is where we are" (location.png,
268	  // map-pin.svg, map_marker.webp, …) — the wrapping link's text is the address.
269	  const PIN_ICON = /(?:location|map[-_]?pin|map[-_]?marker)[^/]*\.(?:png|svg|gif|jpe?g|webp|ico)/i;
270	
271	  // Last-resort location: the street address a single-venue site (a club, a
272	  // cinema, a theater) publishes once in its page chrome instead of repeating
273	  // it in every event's details. The footer is scanned first, then the header
274	  // (some venues use a top contact bar). Only deliberate "this is our address"
275	  // markers are read — never arbitrary chrome text — in signal-strength order:
276	  //   1. a maps-service link (Google Maps, Waze, OSM, Apple/Bing Maps)
277	  //   2. an element whose class/id mentions "addres" (covers "address" and the
278	  //      bare "addres" misspelling seen in the wild)
279	  //   3. a link marked by a location-pin icon (PIN_ICON above)
280	  // Each candidate must still read like a street address (looksLikeAddress), so
281	  // "Get Directions" links, phone numbers, and copyright lines never qualify.
282	  // Ranked below every event-specific signal (including the "(Online)" title
283	  // inference): chrome describes the site, so on a multi-venue platform an
284	  // office address in the footer must lose to any per-event location the page
285	  // exposes — platforms publish JSON-LD/meta locations, which win far earlier.
286	  function chromeAddress() {
287	    const markers = [
288	      (root) => [...root.querySelectorAll("a[href]")].filter((a) => MAPS_SERVICE.test(a.getAttribute("href"))),
289	      (root) => root.querySelectorAll('[class*="addres" i], [id*="addres" i]'),
290	      (root) =>
291	        [...root.querySelectorAll("a")].filter((a) =>
292	          [...a.querySelectorAll("img")].some((img) =>
293	            PIN_ICON.test(`${img.getAttribute("src") || ""} ${img.getAttribute("data-src") || ""}`)
294	          )
295	        ),
296	    ];
297	    for (const scope of ['footer, [class*="footer" i], [id*="footer" i]', 'header, [class*="header" i], [id*="header" i]']) {
298	      const roots = document.querySelectorAll(scope);
299	      for (const marked of markers) {
300	        for (const root of roots) {
301	          for (const el of marked(root)) {
302	            const address = addressText(el);
303	            if (address) return withSiteVenue(address);
304	          }
305	        }
306	      }
307	    }
308	    return "";
309	  }
310	
311	  // The candidate's own visible text. In a real (scripting-enabled) Chrome a
312	  // <noscript>'s content is one RAW TEXT node — naive textContent would splice
313	  // image markup into the address (the gcec RULES.md jsdom-vs-Chrome trap
314	  // that bit custom/telavivcinematheque.js) — so noscript/script/style subtrees
315	  // are dropped from a clone before reading. A leading "Address:"-style label
316	  // is dropped too.
317	  function addressText(el) {
318	    const copy = el.cloneNode(true);
319	    for (const n of copy.querySelectorAll("noscript, script, style")) n.remove();
320	    const t = clean(copy.textContent).replace(/^(?:address|כתובת)\s*:\s*/i, "");
321	    return looksLikeAddress(t) ? t : "";
322	  }
323	
324	  // A plausible one-line street address: short, carries a street number, is
325	  // mostly words rather than digits (a phone number is the reverse), and isn't
326	  // an email / URL / copyright line.
327	  function looksLikeAddress(t) {
328	    if (t.length < 5 || t.length > 120) return false;
329	    const letters = (t.match(/\p{L}/gu) || []).length;
330	    const digits = (t.match(/\d/g) || []).length;
331	    if (!digits || letters < 3 || letters < digits) return false;
332	    return !/[@©]|https?:|copyright|all rights reserved|כל הזכויות/i.test(t);
333	  }
334	
335	  // On a single-venue site the site IS the venue, so when the page names itself
336	  // (og:site_name) the venue leads the composed location — "<venue>, <address>"
337	  // — the way a dedicated single-venue source (and a human typing a Calendar
338	  // location) writes it. Skipped when the name already appears in the address,
339	  // or is merely the site's domain ("stubhub.com" is not a venue).
340	  function withSiteVenue(address) {
341	    const site = clean(meta("og:site_name"));
342	    if (!site || address.includes(site) || /^[\w.-]+\.[a-z]{2,}$/i.test(site)) return address;
343	    return `${site}, ${address}`;
344	  }
345	
346	  // First element matching `sel` whose text is plausibly a venue string
347	  // (short, non-empty) rather than a whole section of the page.
