1	// DOM-reading helpers shared by the extract layers and per-source extractors:
2	// whitespace-normalized text from a selector, the first non-empty of several
3	// selectors, meta-tag content, the page's body text, and the parsed JSON of an
4	// embedded <script> (e.g. Next.js's #__NEXT_DATA__ state blob).
5	//
6	// Augments globalThis.GCal (never replaces it) so load order can't clobber
7	// another file's contributions.
8	globalThis.GCal = Object.assign(globalThis.GCal || {}, (() => {
9	  function clean(s) {
10	    return (s || "").replace(/\s+/g, " ").trim();
11	  }
12	
13	  function text(sel, root) {
14	    const el = (root || document).querySelector(sel);
15	    return el ? clean(el.textContent) : "";
16	  }
17	
18	  function firstText(selectors, root) {
19	    for (const sel of selectors) {
20	      const t = text(sel, root);
21	      if (t) return t;
22	    }
23	    return "";
24	  }
25	
26	  function meta(nameOrProp) {
27	    const el = document.querySelector(
28	      `meta[property="${nameOrProp}"], meta[name="${nameOrProp}"], meta[itemprop="${nameOrProp}"]`
29	    );
30	    return el ? clean(el.getAttribute("content")) : "";
31	  }
32	
33	  function bodyText() {
34	    const body = document.body;
35	    if (!body) return "";
36	    return body.innerText || body.textContent || "";
37	  }
38	
39	  // Parse the JSON content of the <script> matching `selector` (e.g. an id like
40	  // "#__NEXT_DATA__" or '[type="application/json"]'). Returns the parsed value,
41	  // or null when the script is absent or its content isn't valid JSON — so
42	  // callers can navigate the result with plain `&&` guards instead of each
43	  // wrapping its own getElementById + JSON.parse + try/catch.
44	  function jsonScript(selector) {
45	    const el = document.querySelector(selector);
46	    if (!el) return null;
47	    try {
48	      return JSON.parse(el.textContent);
49	    } catch (e) {
50	      return null;
51	    }
52	  }
53	
54	  return { clean, text, firstText, meta, bodyText, jsonScript };
55	})());
