"use strict";
const { readFileSync, readdirSync, existsSync } = require("node:fs");
const path = require("node:path");
const { JSDOM } = require("jsdom");
const ROOT = "/home/user/GoogleCalendarEventCreator";
const EXT = path.join(ROOT, "extension");
const CASES_DIR = path.join(ROOT, "dev/requirements/extractor/expected");
const { dataFile } = require(path.join(ROOT, "dev/requirements/extractor/data-files"));
const SOURCES = JSON.parse(readFileSync(path.join(EXT, "event-extractors/load-order.generated.json"), "utf8")).map((f) =>
  readFileSync(path.join(EXT, f), "utf8")
);

const only = process.argv[2] || "";
for (const file of readdirSync(CASES_DIR).filter((f) => f.endsWith(".json")).sort()) {
  const name = path.basename(file, ".json");
  if (only && !name.includes(only)) continue;
  const urlPath = dataFile(`${name}.url`), htmlPath = dataFile(`${name}.html`);
  if (!existsSync(urlPath) || !existsSync(htmlPath)) continue;
  const url = readFileSync(urlPath, "utf8").trim();
  const dom = new JSDOM(readFileSync(htmlPath, "utf8"), { url, runScripts: "outside-only" });
  try {
    for (const src of SOURCES) dom.window.eval(src);
    const r = JSON.parse(
      dom.window.eval(`JSON.stringify({
        ogd: GCal.meta("og:description"),
        d: GCal.meta("description"),
        ip: GCal.blockText('[itemprop="description"]'),
        ldDesc: (GCal.embeddedEvents.find()[0]||{}).description || "",
        custom: (GCal.extract().events[0]||{}).details || ""
      })`)
    );
    console.log("###", name);
    for (const k of ["ogd", "d", "ip", "ldDesc"]) if (r[k]) console.log("  " + k + ": " + JSON.stringify(String(r[k]).slice(0, 200)));
    console.log("  CUSTOM: " + JSON.stringify(String(r.custom).slice(0, 300)));
  } finally {
    dom.window.close();
  }
}

