1	// Field-by-field merge of partial event objects: the first source with a
2	// non-empty value for a field wins. The two-layer extraction composes through
3	// this — assemble-events.js merges a site source's overrides over the core
4	// generic extractor's base event, so a source states only the fields it gets
5	// better and the base fills the rest.
6	//
7	// Augments globalThis.GCal (never replaces it) so load order can't clobber
8	// another file's contributions.
9	globalThis.GCal = Object.assign(globalThis.GCal || {}, (() => {
10	  function merge(...sources) {
11	    const out = {};
12	    for (const key of ["title", "start", "end", "location", "description", "ctz", "eventLengthInMinutes"]) {
13	      for (const src of sources) {
14	        if (src && src[key]) {
15	          out[key] = src[key];
16	          break;
17	        }
18	      }
19	    }
20	    return out;
21	  }
22	
23	  return { merge };
24	})());
